ValidationRule.errorConditionFormula:
AND(
    ISPICKVAL(Case_Typee__c, "Credit Rebate"),
    OR(
        AND(
            PICKLISTCOUNT(Case_Type__c) > 1,
            NOT(INCLUDES(Case_Type__c, "Weight difference"))
        ),
        AND(
            INCLUDES(Case_Type__c, "Weight difference"),
            OR(
                INCLUDES(Case_Type__c, "Shortage/Damage"),
                INCLUDES(Case_Type__c, "Rate Difference")
            )
        )
    )
)
